static double[] pdFromKvKa(double kV, double kA, double maxPosErr, double maxVelErr,
                           double maxVolts, double dt, double delaySec) {
  var plant = LinearSystemId.identifyPositionSystem(kV, kA);
  var lqr = new LinearQuadraticRegulator<>(plant,
      VecBuilder.fill(maxPosErr, maxVelErr), VecBuilder.fill(maxVolts), dt);
  lqr.latencyCompensate(plant, dt, delaySec);
  return new double[]{ lqr.getK().get(0,0), lqr.getK().get(0,1) }; // kP, kD
}

// O(1) memory regardless of sample count
class FFRegression {           // arm: [cos(theta), sgn(v), v, a]
  private final Matrix<N4,N4> xtx = new Matrix<>(Nat.N4(), Nat.N4());
  private final Matrix<N4,N1> xty = new Matrix<>(Nat.N4(), Nat.N1());
  void add(double theta, double v, double a, double volts) {
    var x = VecBuilder.fill(Math.cos(theta), Math.signum(v), v, a);
    xtx.plusEqu(x.times(x.transpose()));  xty.plusEqu(x.times(volts));
  }
  double[] solve() { var g = xtx.solveFullPivHouseholderQr(xty);
    return new double[]{ g.get(0,0)/*kG*/, g.get(1,0)/*kS*/, g.get(2,0)/*kV*/, g.get(3,0)/*kA*/ }; }
}

